def btn(label, href='contact.html', light=False, extra=''):
    return f'<a class="btn {"btn-light" if light else ""} {extra}" href="{href}">{label}<span class="arrow-disc">{ARROW}</span></a>'

def textlink(label, href):
    return f'<a class="text-link" href="{href}">{label}{ARROW}</a>'

def scene(kind, caption, extra=''):
    return f'''<div class="scene-shell {extra}"><div class="scene" data-scene="{kind}"><picture><source media="(max-width:700px)" srcset="assets/images/sculpture-{kind}-mobile.webp"><img class="scene-poster" src="assets/images/sculpture-{kind}.webp" width="960" height="800" alt="" fetchpriority="high"></picture></div><button class="scene-control" data-scene-toggle aria-pressed="false">Pause interaction</button><span class="scene-caption" aria-hidden="true">{caption}</span></div>'''

def header(key, dark=False):
    def link(slug,label):
        active=' aria-current="page"' if slug==key else ''
        return f'<a class="nav-link" href="{slug}.html"{active}>{label}</a>'
    return f'''<a class="skip-link" href="#main-content">Skip to content</a><header class="site-header"><div class="container header-inner"><a class="brand" href="index.html" aria-label="LUMA home"><img src="assets/images/luma-logo-{'white' if dark else 'dark'}-small.webp" alt="LUMA — Business registration and compliance" width="132" height="43"></a><nav class="desktop-nav" aria-label="Main navigation"><div class="nav-dropdown"><button aria-expanded="false" aria-controls="services-menu" data-services>Our services <svg viewBox="0 0 12 8" fill="none" stroke="currentColor" aria-hidden="true"><path d="m1 1 5 5 5-5"/></svg></button><div class="nav-dropdown-menu" id="services-menu" hidden>{link('business-registration','Business registration')}{link('managed-compliance','Managed compliance')}</div></div>{link('how-it-works','How it works')}{link('pricing','Pricing')}{link('about','About')}{link('resources','Resources')}</nav>{btn('Let’s talk',extra='header-cta')}<button class="menu-toggle" aria-label="Open navigation" aria-expanded="false" aria-controls="mobile-menu"><span></span><span></span></button></div><nav class="mobile-menu" id="mobile-menu" aria-label="Mobile navigation" hidden>{''.join(link(s,l) for s,l in NAV)}</nav></header>'''

def footer():
    return f'''<footer class="site-footer"><div class="container"><div class="footer-top"><div class="footer-intro"><a class="footer-brand" href="index.html" aria-label="LUMA home">{MARK}<span>Luma</span></a><p>More space for your ambition.<br>A stronger foundation for your business.</p></div><div class="footer-col"><h3>Build & grow</h3><a href="business-registration.html">Business registration</a><a href="managed-compliance.html">Managed compliance</a><a href="how-it-works.html">How it works</a><a href="pricing.html">Pricing</a></div><div class="footer-col"><h3>Explore LUMA</h3><a href="about.html">Our approach</a><a href="resources.html">Resource library</a><a href="faq.html">Your questions</a><a href="contact.html">Start a conversation</a></div><div class="footer-col"><h3>Made for Cameroon</h3><a href="business-registration.html#structures">Local founders</a><a href="about.html#diaspora">Diaspora founders</a><a href="about.html#privacy">Privacy & your enquiry</a></div></div><div class="footer-bottom"><span>© 2026 LUMA. All rights reserved.</span><p>LUMA is an independent business coordination service, not a government authority. Registration and filing decisions remain with the relevant authorities and professionals.</p></div><div class="footer-wordmark" aria-hidden="true"><img src="assets/images/luma-logo-white.png" alt="" width="1400" height="400" loading="lazy"></div></div></footer>'''

def closing(title='Your next chapter.<br>On solid ground.', label='Build with LUMA'):
    return f'<section class="closing" data-od-id="closing"><div class="container closing-inner"><h2>{title}</h2>{btn(label)}</div></section>'

def hero(kind, label, title, copy, action='Explore the details', target='#details'):
    return f'''<section class="page-hero hero-{kind}" data-od-id="hero"><div class="container page-hero-inner"><div class="hero-copy"><span class="eyebrow">{label}</span><h1>{title}</h1><p class="lede">{copy}</p><div class="actions">{btn(action,target)}</div></div>{scene(kind, {'journey':'A clear path, from the start','registration':'The foundation of your next chapter','compliance':'Continuity, by design','pricing':'Every layer, accounted for','about':'A different kind of business partner','resources':'Knowledge worth keeping','faq':'Clarity starts with a question'}.get(kind,''))}</div></section>'''

def chapter(left, right='Explore below', target='#details'):
    return f'<div class="container"><div class="page-chapter"><span>{left}</span><a href="{target}">{right}{ARROW}</a></div></div>'

def rows(items, cls='detail-row'):
    return ''.join(f'<div class="{cls}"'+(f' id="step-{i:02}"' if cls=='journey-step' else '')+f'><span>{i:02}</span><div><h3>{title}</h3><p>{copy}</p></div></div>' for i,(title,copy) in enumerate(items,1))

def film(name, title, caption, portrait=False):
    return f'''<figure><div class="{'media-portrait' if portrait else 'film-frame'}"><video data-film src="assets/videos/{name}-web.mp4" poster="assets/images/{name}-poster.webp" data-src="assets/videos/{name}-web.mp4" data-poster="assets/images/{name}-poster.webp" autoplay muted loop playsinline preload="auto" aria-label="{escape(title)}"></video><noscript><img src="assets/images/{name}-poster.webp" alt="{escape(title)}" width="1280" height="720" loading="lazy"></noscript>{'' if portrait else f'<figcaption class="film-caption">{caption}<small>Illustrative generated scene</small></figcaption>'}</div>{'<figcaption class="image-note">Illustrative generated scene. Not a photograph of LUMA staff or clients.</figcaption>' if portrait else ''}</figure>'''

